const timePermutations = createPermutations<LineChartProps<Date>>([
  // Date/time series
  {
    i18nStrings: [{ ...commonProps.i18nStrings, xTickFormatter: dateTimeFormatter }],
    ariaLabel: ['Test chart'],
    height: [200],
    series: [
      [{ title: 'Series 1', type: 'line', data: timeLatencyData }],
      [
