    xDomain: [[new Date(1601017200000), new Date(1601028900000)]],
    yDomain: [[0, 500000]],
    xTitle: ['Time (UTC)'],
    yTitle: ['Bytes transferred'],
    hideFilter: [true],
    hideLegend: [true],
  },
